import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Split a log file into its comment header and its body using
 * takeWhile and dropWhile (Java 9+).
 *
 * A log starts with zero or more header lines that begin with "#".
 * Everything from the first non-"#" line onwards is the body.
 *
 * headerLines: the leading "#" lines, each with the "#" removed and the
 *              remaining text trimmed.
 * bodyLines:   every line from the first non-"#" line onwards, UNCHANGED --
 *              including any "#" lines that appear later in the file.
 *
 * Example input: ["# name: build", "#  v2 ", "start", "# not a header", "done"]
 *   headerLines -> ["name: build", "v2"]
 *   bodyLines   -> ["start", "# not a header", "done"]
 *
 * EDGE CASES: a log with no "#" lines has an empty header and a full body;
 * a log that is all "#" lines has a full header and an empty body.
 */
public class LogSectionSplitter {

    public static List<String> headerLines(List<String> lines) {
        return lines.stream()
                .takeWhile(line -> line.startsWith("#"))
                .map(line -> line.substring(1).trim())
                .collect(java.util.stream.Collectors.toList());
    }

    public static List<String> bodyLines(List<String> lines) {
        return lines.stream()
                .dropWhile(line -> line.startsWith("#"))
                .collect(java.util.stream.Collectors.toList());
    }
}
